package repositories
import("context";"errors";"regexp";"time";"github.com/ngwebwork/payflow/internal/models";"go.mongodb.org/mongo-driver/bson";"go.mongodb.org/mongo-driver/bson/primitive";"go.mongodb.org/mongo-driver/mongo";"go.mongodb.org/mongo-driver/mongo/options")
type SubscriptionQuery struct{Page,Limit int;Search,Status string};type SubscriptionPage struct{Items []models.Subscription `json:"items"`;Page int `json:"page"`;Limit int `json:"limit"`;Total int64 `json:"total"`;TotalPages int `json:"totalPages"`};type SubscriptionSummary struct{MonthlyRecurringRevenue float64 `json:"monthlyRecurringRevenue"`;ActiveSubscriptions int64 `json:"activeSubscriptions"`;UpcomingRenewals int64 `json:"upcomingRenewals"`};type SubscriptionRepository struct{subscriptions,customers *mongo.Collection}
func NewSubscriptionRepository(db *mongo.Database)(*SubscriptionRepository,error){r:=&SubscriptionRepository{db.Collection("subscriptions"),db.Collection("customers")};_,e:=r.subscriptions.Indexes().CreateMany(context.Background(),[]mongo.IndexModel{{Keys:bson.D{{Key:"userId",Value:1},{Key:"createdAt",Value:-1}}},{Keys:bson.D{{Key:"customerId",Value:1}}},{Keys:bson.D{{Key:"status",Value:1}}},{Keys:bson.D{{Key:"nextPaymentDate",Value:1}}}});return r,e};func(r *SubscriptionRepository) Customer(c context.Context,u,id primitive.ObjectID)(*models.Customer,error){var x models.Customer;e:=r.customers.FindOne(c,bson.M{"_id":id,"userId":u}).Decode(&x);if errors.Is(e,mongo.ErrNoDocuments){return nil,nil};return &x,e};func(r *SubscriptionRepository) Create(c context.Context,x *models.Subscription)error{_,e:=r.subscriptions.InsertOne(c,x);return e};func(r *SubscriptionRepository) Get(c context.Context,u,id primitive.ObjectID)(*models.Subscription,error){var x models.Subscription;e:=r.subscriptions.FindOne(c,bson.M{"_id":id,"userId":u}).Decode(&x);if errors.Is(e,mongo.ErrNoDocuments){return nil,nil};return &x,e}
func(r *SubscriptionRepository) List(c context.Context,u primitive.ObjectID,q SubscriptionQuery)(SubscriptionPage,error){f:=bson.M{"userId":u};if q.Status!=""{f["status"]=q.Status};if q.Search!=""{f["plan"]=bson.M{"$regex":regexp.QuoteMeta(q.Search),"$options":"i"}};n,e:=r.subscriptions.CountDocuments(c,f);if e!=nil{return SubscriptionPage{},e};cur,e:=r.subscriptions.Find(c,f,options.Find().SetSort(bson.D{{Key:"createdAt",Value:-1}}).SetSkip(int64((q.Page-1)*q.Limit)).SetLimit(int64(q.Limit)));if e!=nil{return SubscriptionPage{},e};defer cur.Close(c);var x []models.Subscription;e=cur.All(c,&x);return SubscriptionPage{x,q.Page,q.Limit,n,int((n+int64(q.Limit)-1)/int64(q.Limit))},e};func(r *SubscriptionRepository) Update(c context.Context,u,id primitive.ObjectID,x *models.Subscription)error{x.UpdatedAt=time.Now().UTC();v,e:=r.subscriptions.ReplaceOne(c,bson.M{"_id":id,"userId":u},x);if e==nil&&v.MatchedCount==0{return mongo.ErrNoDocuments};return e};func(r *SubscriptionRepository) Cancel(c context.Context,u,id primitive.ObjectID)error{v,e:=r.subscriptions.UpdateOne(c,bson.M{"_id":id,"userId":u},bson.M{"$set":bson.M{"status":"cancelled","updatedAt":time.Now().UTC()}});if e==nil&&v.MatchedCount==0{return mongo.ErrNoDocuments};return e}
func(r *SubscriptionRepository) Summary(c context.Context,u primitive.ObjectID)(SubscriptionSummary,error){f:=bson.M{"userId":u,"status":"active"};n,e:=r.subscriptions.CountDocuments(c,f);if e!=nil{return SubscriptionSummary{},e};cur,e:=r.subscriptions.Aggregate(c,mongo.Pipeline{{{Key:"$match",Value:bson.M{"userId":u,"status":"active","billingCycle":"monthly"}}},{{Key:"$group",Value:bson.M{"_id":nil,"sum":bson.M{"$sum":"$amount"}}}}});if e!=nil{return SubscriptionSummary{},e};defer cur.Close(c);var a []struct{Sum float64 `bson:"sum"`};if e=cur.All(c,&a);e!=nil{return SubscriptionSummary{},e};up,e:=r.subscriptions.CountDocuments(c,bson.M{"userId":u,"status":"active","nextPaymentDate":bson.M{"$gte":time.Now().UTC(),"$lt":time.Now().UTC().AddDate(0,1,0)}});if e!=nil{return SubscriptionSummary{},e};s:=SubscriptionSummary{ActiveSubscriptions:n,UpcomingRenewals:up};if len(a)>0{s.MonthlyRecurringRevenue=a[0].Sum};return s,nil}
